head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isUpdate = false;
scwin.storageId = "";

// 수정 여부

///////// 2. 초기화 영역 /////////
            scwin.onpageload = function() {

                scwin.vScrenID = "ULDTMS04060.xml";
                scwin.storageId = $c.data.getParameter("storageId");

                // 상장고시 시장구분코드
                const list = ["LD_MKT_TP_CD"];
                const params = {"cdEngNmList":list};

                // 시장구분 정보 조회
                $c.sbm.execute(sbm_ldMktTpCd, params);		
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.ibx_formProcsCd_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_formProcsCd);
                // 양수만 되게 수정
                ibx_formProcsCd.setValue((ibx_formProcsCd.getValue()).replace(/[^0-9]/g, ""));
            };

            scwin.btn_save_onclick = async function (e) {

                // validation 체크
                if (!$c.tms.validateGroupTms("grp_input")) return;

                if (scwin.isUpdate) {                                           
                    $c.sbm.setAction(sbm_save, "/api/code/procs-procs/update/" + dma_save.get("formProcsCd"));
                }
                // 이중 클릭 방지
                btn_save.setDisabled(true);
                // 코드 정보 저장
                $c.sbm.execute(sbm_save, dma_save.getJSON());                
            };

            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_ldMktTpCd_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {                    
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body, sbx_ldMktTpCd, "cdValNm", "cdVal", "LD_MKT_TP_CD", "cdEngNm");
                } else {
                    $c.win.alert(result.message);
                }              

                setTimeout(function () {                                                       
                    const formProcsCd = $c.data.getParameter("formProcsCd");
                    if (!$c.util.isEmpty(formProcsCd)) {
                        dma_save.set("formProcsCd", formProcsCd);                        
                        dma_save.set("ldMktTpCd", $c.data.getParameter("ldMktTpCd"));
                        dma_save.set("formProcsNm", $c.data.getParameter("formProcsNm"));

                        ibx_formProcsCd.setDisabled(true);
                        btn_save.setValue("변경 저장");
                        scwin.isUpdate = true;
                    }
                }, 100);
            };

            scwin.sbm_save_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("저장 되었습니다.");

                    let params = {};
                    params.refreshYn = "Y";
                    params.storageId = scwin.storageId;

                    $c.win.closePopup(params);
                } else {
                    $c.win.alert(result.message);
                }
                // 이중 클릭 해제
                btn_save.setDisabled(false);
            };
